insert into public.pulse_challenge_templates (id, code, title, description, category, difficulty, points, answer_type, options, scoring_rule, required_facts, active, priority, cooldown_days, tags)
select 'cht_' || lower(code), code, title, description, category, difficulty, points, "answerType", options, rule, array['home_score','away_score']::text[], true, priority, cooldown, array(select jsonb_array_elements_text(tags))
from jsonb_to_recordset($json$[{"code":"AWAY_GTE_8","title":"¿El visitante llega a 8 o más?","description":"Se corrige con el marcador final.","category":"resultado","difficulty":"expert","points":8,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"away_gte","n":8},"priority":0,"cooldown":2,"tags":["resultado"]},{"code":"TOTAL_LTE_4","title":"¿El partido se queda en 4 carreras o menos?","description":"Se corrige con el marcador final.","category":"defensiva","difficulty":"expert","points":10,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"total_lte","n":4},"priority":0,"cooldown":2,"tags":["defensiva"]},{"code":"EITHER_GTE_4","title":"¿Algún equipo anota 4 o más?","description":"Se corrige con el marcador final.","category":"ofensiva","difficulty":"easy","points":2,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"either_gte","n":4},"priority":0,"cooldown":2,"tags":["ofensiva"]},{"code":"WINNER_GTE_10","title":"¿El ganador llega a 10 o más?","description":"Se corrige con el marcador final.","category":"resultado","difficulty":"expert","points":10,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"winner_gte","n":10},"priority":0,"cooldown":2,"tags":["resultado"]}]$json$::jsonb) as t(code text, title text, description text, category text, difficulty text, points int, "answerType" text, options jsonb, rule jsonb, priority int, cooldown int, tags jsonb)
on conflict (code) do nothing;